+#[must_use]
+pub fn joins_blank_scope(pattern: &GraphPattern) -> bool {
+    match pattern {
+        GraphPattern::Join { .. } => true,
+        GraphPattern::Lateral { right, .. } => {
+            matches!(&**right, GraphPattern::PropertyFunction(_))
