+/// Semantic categories whose identity rules differ.
+#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
+pub enum Category {
+    User,
+    Existential,
+    Witness,
+    TemplateAllocation,
+    DatasetBlank,
+}
