+/// Where a binding acquired its identity.
+#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
+pub enum Origin {
+    SourceVariable,
+    SourceBlank,
+    PathTranslation,
+    Template,
+    DatasetParameter,
+}
