+/// Declaration carried by the explicit representation candidate.
+#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
+pub struct Binder {
+    pub id: u32,
+    pub category: Category,
+    pub origin: Origin,
+    pub owner: u32,
