+/// One comparison row: fixture construction names never steer detectors.
+pub struct Case {
+    pub name: &'static str,
+    pub before: Evidence,
+    pub after: Evidence,
+    pub correspondence: BTreeMap<Identity, Identity>,
+    pub legal: bool,
+    pub claim: &'static str,
+}
+
+fn case(
+    name: &'static str,
+    before: &Evidence,
+    after: Evidence,
+    legal: bool,
+    claim: &'static str,
+) -> Case {
+    Case {
+        name,
+        before: before.clone(),
+        after,
+        correspondence: BTreeMap::new(),
+        legal,
+        claim,
+    }
+}
