+fn register_concrete_blank_inputs<D: DatasetView + Sync>(
+    pattern: &GraphPattern,
+    ctx: &mut EvalCtx<'_, D>,
+) {
+    use purrdf_sparql_algebra::{Flow, GroundTerm, NodeRef, Visit, walk_pre_post};
